{
  "name": "quattromap",
  "description": "Compare up to 4 maps at once",
  "version": "2.0.0",
  "license": "MIT",
  "scripts": {
    "start": "webpack serve",
    "build": "webpack",
    "deploy": "gh-pages -d dist"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/kreis-viersen/quattromap"
  },
  "devDependencies": {
    "copy-webpack-plugin": "^14.0.0",
    "css-loader": "^7.1.5",
    "gh-pages": "^6.3.0",
    "style-loader": "^4.0.0",
    "terser-webpack-plugin": "^5.6.1",
    "webpack": "^5.110.3",
    "webpack-cli": "^7.2.3",
    "webpack-dev-server": "^6.0.0",
    "webpack-license-plugin": "^4.5.1"
  },
  "dependencies": {
    "@mapbox/mapbox-gl-draw": "1.5.1",
    "@mapbox/mapbox-gl-sync-move": "^0.3.1",
    "@maplibre/maplibre-gl-geocoder": "^1.9.4",
    "@turf/area": "^7.4.0",
    "@turf/centroid": "^7.4.0",
    "@turf/length": "^7.4.0",
    "lz-string": "^1.5.0",
    "maplibre-gl": "6.9.0"
  }
}---WEBPACK---
const CopyPlugin = require('copy-webpack-plugin');
const LicensePlugin = require('webpack-license-plugin');
const TerserPlugin = require('terser-webpack-plugin');
const path = require('path');

module.exports = {
  mode: 'production',
  entry: './src/index.js',
  optimization: {
    minimizer: [
      new TerserPlugin({
        extractComments: false,
      }),
    ],
  },
  devServer: {
    client: {
      overlay: {
        errors: true,
        warnings: false,
      },
    },
    devMiddleware: {
      stats: 'minimal',
    },
  },
  output: {
    filename: 'bundle.js',
    path: path.resolve(__dirname, 'dist'),
  },
  module: {
    rules: [
      {
        test: /\.css$/i,
        use: ['style-loader', 'css-loader'],
      },
    ],
  },
  plugins: [
    new CopyPlugin({
      patterns: [
        {
          from: './src/index.html',
          to: 'index.html',
        },
        {
          from: './src/img',
          to: 'img',
        },
        {
          from: './node_modules/maplibre-gl/dist/maplibre-gl-worker.mjs',
          to: 'vendor/maplibre/maplibre-gl-worker.mjs',
        },
        {
          from: './node_modules/maplibre-gl/dist/maplibre-gl-shared.mjs',
          to: 'vendor/maplibre/maplibre-gl-shared.mjs',
        },
      ],
    }),
    new LicensePlugin({
      licenseOverrides: {
        // https://github.com/codepunkt/webpack-license-plugin/issues/443
        '@mapbox/fusspot@0.4.0': 'BSD-2-Clause'
      },
      // mapbox-gl uses a custom license
      excludedPackageTest: name => name === 'mapbox-gl',
      additionalFiles: {
        'oss-licenses.json': packages => JSON.stringify([...packages, {
          'name': 'mapbox-gl',
          'version': '1.13.1',
          'repository': 'https://github.com/mapbox/mapbox-gl-js',
          'license': "Mapbox license",
          'licenseText': 'content of LICENSE.txt in mapbox-gl-js root directory: https://raw.githubusercontent.com/mapbox/mapbox-gl-js/v1.13.1/LICENSE.txt'
        }], null, 2)
      }
    }),
  ],
};
